<?php require_once __DIR__.'/includes/functions.php';require_role(['student']);$uid=current_user()['id'];$s=$conn->prepare("SELECT s.*,c.code course_code,se.section_name assigned_section,se.year_level section_year FROM students s LEFT JOIN courses c ON c.id=s.course_id LEFT JOIN sections se ON se.id=s.section_id WHERE s.user_id=?");$s->bind_param('i',$uid);$s->execute();$st=$s->get_result()->fetch_assoc();$fullName='';if($st){$middleName=trim($st['middle_name']??'');$fullName=trim($st['first_name'].' '.($middleName!==''?$middleName.' ':'').$st['last_name']);}include 'includes/header.php';?><h3 class="mb-3 no-print">My Student ID</h3><?php if(!$st):?><div class="alert info">Your student record has not yet been linked by the Registrar.</div><?php else:?><div class="id-card"><img class="id-watermark" src="assets/725698283_122272196210063653_4714758265439461367_n.jpg" alt=""><div class="id-head"><span class="id-mark">CCST</span><span>STUDENT IDENTIFICATION</span></div><div class="id-body"><img class="id-photo" src="<?=e($st['photo']?UPLOAD_URL.$st['photo']:'assets/avatar.svg')?>"><div class="id-details"><div class="id-code"><?=e($st['student_code'])?></div><h4><?=e($fullName)?></h4><dl class="id-facts"><div><dt>Course</dt><dd><?=e($st['course_code']??'Not assigned')?></dd></div><div><dt>Year level</dt><dd><?=e($st['section_year']??$st['year_level']??'Not assigned')?></dd></div><div><dt>Section</dt><dd><?=e($st['assigned_section']??'Not assigned')?></dd></div><div><dt>Status</dt><dd><?=e(ucfirst($st['status']))?></dd></div></dl></div></div><div class="id-qr-area"><div id="qrcode" class="qr"></div></div></div><div class="text-center mt-3 no-print"><button class="btn btn-primary" onclick="window.print()">Print ID</button></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>new QRCode(document.getElementById('qrcode'),{text:<?=json_encode($st['student_code'])?>,width:112,height:112});</script><?php endif;?><?php include 'includes/footer.php';?>
